s_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"html_url":"https://github.com/oberhamberger/cohbrgr/commit/35af7e48d30eb8d76b5d9a94e4d1bb76db79f268","node_id":"C_kwDOFO40ItoAKDM1YWY3ZTQ4ZDMwZWI4ZDc2YjVkOWE5NGU0ZDFiYjc2ZGI3OWYyNjg","parents":[{"html_url":"https://github.com/oberhamberger/cohbrgr/commit/50435df38454d7ceb1ed9944cb5f3d24573693cc","sha":"50435df38454d7ceb1ed9944cb5f3d24573693cc","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/50435df38454d7ceb1ed9944cb5f3d24573693cc"},{"html_url":"https://github.com/oberhamberger/cohbrgr/commit/2ccf615ea2b792864209b3c9d5fc22c1d928ceb8","sha":"2ccf615ea2b792864209b3c9d5fc22c1d928ceb8","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/2ccf615ea2b792864209b3c9d5fc22c1d928ceb8"}],"sha":"35af7e48d30eb8d76b5d9a94e4d1bb76db79f268","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/35af7e48d30eb8d76b5d9a94e4d1bb76db79f268"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"comments_url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/2ccf615ea2b792864209b3c9d5fc22c1d928ceb8/comments","commit":{"author":{"date":"2026-08-30T08:12:45Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"comment_count":0,"committer":{"date":"2026-08-30T08:12:45Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"message":"fix(a11y): keep the visible mark inside its accessible name\n\nLighthouse fails label-content-name-mismatch at error level on the homepage:\n\n  <a href=\"/codex\" aria-label=\"Codex Visioque\">\n  Text inside the element is not included in the accessible name\n\nMy own doing. The aria-label was added so C·V·Q·O would not announce as four\nletters, but replacing the name breaks WCAG 2.5.3 — a speech-input user says\nwhat they can see, and \"C·V·Q·O\" was no longer in the name they could activate.\n\nThe expansion is now appended in a visually hidden span instead of overriding,\nso the accessible name reads \"C·V·Q·O — Codex Visioque\" and contains the visible\ntext. Adds a .sr-only utility to the global stylesheet, which the content remote\ncan use because that sheet is not scoped.\n\nThe e2e assertion moves from checking the aria-label attribute to\ntoHaveAccessibleName, which tests the thing the audit actually cares about.\n\nLighthouse now reports zero error-level failures; the remaining ones are the\nthree warns already configured in .lighthouserc.js.","tree":{"sha":"ba402a2fd01ab961e293cfff58411cc040a14acb","url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/trees/ba402a2fd01ab961e293cfff58411cc040a14acb"},"url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/commits/2ccf615ea2b792864209b3c9d5fc22c1d928ceb8","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"html_url":"https://github.com/oberhamberger/cohbrgr/commit/2ccf615ea2b792864209b3c9d5fc22c1d928ceb8","node_id":"C_kwDOFO40ItoAKDJjY2Y2MTVlYTJiNzkyODY0MjA5YjNjOWQ1ZmMyMmMxZDkyOGNlYjg","parents":[{"html_url":"https://github.com/oberhamberger/cohbrgr/commit/50435df38454d7ceb1ed9944cb5f3d24573693cc","sha":"50435df38454d7ceb1ed9944cb5f3d24573693cc","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/50435df38454d7ceb1ed9944cb5f3d24573693cc"}],"sha":"2ccf615ea2b792864209b3c9d5fc22c1d928ceb8","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/2ccf615ea2b792864209b3c9d5fc22c1d928ceb8"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"comments_url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/50435df38454d7ceb1ed9944cb5f3d24573693cc/comments","commit":{"author":{"date":"2026-08-29T21:55:58Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"comment_count":0,"committer":{"date":"2026-08-29T21:55:58Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"message":"Merge branch ''fix/api-failure-logging''","tree":{"sha":"77ab0e1724eef28dc8bc875444e1e50c1ea643aa","url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/trees/77ab0e1724eef28dc8bc875444e1e50c1ea643aa"},"url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/commits/50435df38454d7ceb1ed9944cb5f3d24573693cc","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"html_url":"https://github.com/oberhamberger/cohbrgr/commit/50435df38454d7ceb1ed9944cb5f3d24573693cc","node_id":"C_kwDOFO40ItoAKDUwNDM1ZGYzODQ1NGQ3Y2ViMWVkOTk0NGNiNWYzZDI0NTczNjkzY2M","parents":[{"html_url":"https://github.com/oberhamberger/cohbrgr/commit/3a7f9cafa7c4315f50720980d670dae73c1a441d","sha":"3a7f9cafa7c4315f50720980d670dae73c1a441d","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/3a7f9cafa7c4315f50720980d670dae73c1a441d"},{"html_url":"https://github.com/oberhamberger/cohbrgr/commit/f43b5f17de0c5bb87f977e53a617b51b6aa1e7aa","sha":"f43b5f17de0c5bb87f977e53a617b51b6aa1e7aa","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/f43b5f17de0c5bb87f977e53a617b51b6aa1e7aa"}],"sha":"50435df38454d7ceb1ed9944cb5f3d24573693cc","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/50435df38454d7ceb1ed9944cb5f3d24573693cc"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"comments_url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/f43b5f17de0c5bb87f977e53a617b51b6aa1e7aa/comments","commit":{"author":{"date":"2026-08-29T21:52:59Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"comment_count":0,"committer":{"date":"2026-08-29T21:52:59Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"message":"refactor(utils): split the package into node and browser entries\n\nThe ./api-failure subpath from the previous commit was a one-off around the real\nproblem: the package had a single ''.'' export whose index reached the winston\nlogger, so any client-side import pulled winston in silently. That is the bug\nthat produced the duplicated helper in the first place.\n\n@cohbrgr/utils now exports ./node — constants, findProcessArgs and the logger,\neverything that assumes a Node runtime — and ./browser for code that runs on\neither side, currently reportApiFailure.\n\nThere is deliberately no ''.'' export, so the boundary is enforced rather than\nadvised. A bare `import from ''@cohbrgr/utils''` now fails type-check with TS2307\ninstead of quietly bundling winston into the browser; verified with a probe\nfile. Both client bundles still contain zero winston references.\n\nTwenty-odd import sites move to /node, the four query files to /browser.","tree":{"sha":"77ab0e1724eef28dc8bc875444e1e50c1ea643aa","url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/trees/77ab0e1724eef28dc8bc875444e1e50c1ea643aa"},"url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/commits/f43b5f17de0c5bb87f977e53a617b51b6aa1e7aa","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"html_url":"https://github.com/oberhamberger/cohbrgr/commit/f43b5f17de0c5bb87f977e53a617b51b6aa1e7aa","node_id":"C_kwDOFO40ItoAKGY0M2I1ZjE3ZGUwYzViYjg3Zjk3N2U1M2E2MTdiNTFiNmFhMWU3YWE","parents":[{"html_url":"https://github.com/oberhamberger/cohbrgr/commit/6f622aa3ffe4e22e40758d90381835b269abce91","sha":"6f622aa3ffe4e22e40758d90381835b269abce91","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/6f622aa3ffe4e22e40758d90381835b269abce91"}],"sha":"f43b5f17de0c5bb87f977e53a617b51b6aa1e7aa","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/f43b5f17de0c5bb87f977e53a617b51b6aa1e7aa"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"comments_url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/6f622aa3ffe4e22e40758d90381835b269abce91/comments","commit":{"author":{"date":"2026-08-29T21:46:04Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"comment_count":0,"committer":{"date":"2026-08-29T21:46:04Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"message":"refactor(utils): move reportApiFailure into the package it belongs in\n\nIt was written twice, once per app, with the specs duplicated alongside. The\nexcuse was that @cohbrgr/utils exports the winston logger from its index and\nwinston has no business in a client bundle — but the fix for that is a boundary,\nnot a copy.\n\n@cohbrgr/utils gains a ./api-failure subpath export, so importing the reporter\nnever reaches the index and never drags winston along. Confirmed: both client\nbundles still contain zero winston references. The helper is deliberately not\nre-exported from the index, so there is one import path and no way to pull the\nlogger in by accident.\n\nEnvironment detection is `''window'' in globalThis` rather than `typeof window`,\nbecause the package compiles with types: [\"node\"] and no DOM lib, and has to\nstay importable from both sides.\n\nFour files became two. One spec now covers both apps.","tree":{"sha":"1e40b1eebafcd6d79211135fc8fa6abca16050d7","url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/trees/1e40b1eebafcd6d79211135fc8fa6abca16050d7"},"url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/commits/6f622aa3ffe4e22e40758d90381835b269abce91","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"html_url":"https://github.com/oberhamberger/cohbrgr/commit/6f622aa3ffe4e22e40758d90381835b269abce91","node_id":"C_kwDOFO40ItoAKDZmNjIyYWEzZmZlNGUyMmU0MDc1OGQ5MDM4MTgzNWIyNjlhYmNlOTE","parents":[{"html_url":"https://github.com/oberhamberger/cohbrgr/commit/3b6b7b9da55a5e960005c02a3a3992253b5dfbe1","sha":"3b6b7b9da55a5e960005c02a3a3992253b5dfbe1","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/3b6b7b9da55a5e960005c02a3a3992253b5dfbe1"}],"sha":"6f622aa3ffe4e22e40758d90381835b269abce91","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/6f622aa3ffe4e22e40758d90381835b269abce91"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"comments_url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/3b6b7b9da55a5e960005c02a3a3992253b5dfbe1/comments","commit":{"author":{"date":"2026-08-29T21:42:21Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"comment_count":0,"committer":{"date":"2026-08-29T21:42:21Z","email":"c.oberhamberger@gmail.com","name":"Christian Oberhamberger"},"message":"fix: log every API failure loudly, and stop reading 304 as one\n\nTwo defects behind today''s incident, where the live navigation silently vanished\nwhile the API answered every request I made from outside.\n\nThe API was returning 429 to the shell. Its rate limiter allows 500 requests per\n10 minutes per IP, and every server-side render arrives from one Cloud Run egress\naddress, so the whole site shares a single client budget. Two API calls per\nrender is all it takes for ordinary traffic, a crawler or a test run to exhaust\nit. That cause is not fixed here — this commit makes it visible.\n\n- Adds reportApiFailure to both apps. Server side it writes a JSON line with\n  severity ERROR so Cloud Logging files it as an error rather than an untyped\n  line, and in the browser it goes to console.error. The `[api-unavailable]`\n  prefix is stable so a log-based alert can match on it alone. Every degrade\n  path now calls it: navigation and translations, in the shell and the content\n  remote.\n- Errors now carry the status, `HTTP 429 Too Many Requests` rather than\n  `Failed to fetch: Too Many Requests`, because the whole point is telling 429\n  and 304 apart in a log.\n\nThe second defect is fetchNavigation itself. Both endpoints answer a conditional\nrequest with 304, which is not `ok` and carries no body to fall back on, so the\nruntime revalidating with If-None-Match produced an empty navigation from a\nperfectly healthy API. One 304 is already in today''s production logs. Both\nfetchers now pass `cache: ''no-store''`.\n\nDegrading rather than throwing is still right — an SSR throw becomes a 500 for\nthe whole page — but it made an outage invisible to everyone except a visitor\nlooking at a missing nav. Verified with the API stopped: four ERROR lines, and\nthe page still renders.","tree":{"sha":"f01bca09f39433b345b6d142defa420c7c697c36","url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/trees/f01bca09f39433b345b6d142defa420c7c697c36"},"url":"https://api.github.com/repos/oberhamberger/cohbrgr/git/commits/3b6b7b9da55a5e960005c02a3a3992253b5dfbe1","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url":"https://api.github.com/users/oberhamberger/followers","following_url":"https://api.github.com/users/oberhamberger/following{/other_user}","gists_url":"https://api.github.com/users/oberhamberger/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/oberhamberger","id":8846578,"login":"oberhamberger","node_id":"MDQ6VXNlcjg4NDY1Nzg=","organizations_url":"https://api.github.com/users/oberhamberger/orgs","received_events_url":"https://api.github.com/users/oberhamberger/received_events","repos_url":"https://api.github.com/users/oberhamberger/repos","site_admin":false,"starred_url":"https://api.github.com/users/oberhamberger/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/oberhamberger/subscriptions","type":"User","url":"https://api.github.com/users/oberhamberger","user_view_type":"public"},"html_url":"https://github.com/oberhamberger/cohbrgr/commit/3b6b7b9da55a5e960005c02a3a3992253b5dfbe1","node_id":"C_kwDOFO40ItoAKDNiNmI3YjlkYTU1YTVlOTYwMDA1YzAyYTNhMzk5MjI1M2I1ZGZiZTE","parents":[{"html_url":"https://github.com/oberhamberger/cohbrgr/commit/3a7f9cafa7c4315f50720980d670dae73c1a441d","sha":"3a7f9cafa7c4315f50720980d670dae73c1a441d","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/3a7f9cafa7c4315f50720980d670dae73c1a441d"}],"sha":"3b6b7b9da55a5e960005c02a3a3992253b5dfbe1","url":"https://api.github.com/repos/oberhamberger/cohbrgr/commits/3b6b7b9da55a5e960005c02a3a3992253b5dfbe1"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/8846578?v=4","events_url":"https://api.github.com/users/oberhamberger/events{/privacy}","followers_url"