so style the remaining toolbar\nbuttons to match the surrounding text-button treatment.","tree":{"sha":"2b57b08490ea7f19c35e157a7b35811ad5856c3c","url":"https://api.github.com/repos/erupts/erupt-web/git/trees/2b57b08490ea7f19c35e157a7b35811ad5856c3c"},"url":"https://api.github.com/repos/erupts/erupt-web/git/commits/497cd16c60c4817beba3170fa36b3776b0f39495","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/20358088?v=4","events_url":"https://api.github.com/users/erupts/events{/privacy}","followers_url":"https://api.github.com/users/erupts/followers","following_url":"https://api.github.com/users/erupts/following{/other_user}","gists_url":"https://api.github.com/users/erupts/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/erupts","id":20358088,"login":"erupts","node_id":"MDQ6VXNlcjIwMzU4MDg4","organizations_url":"https://api.github.com/users/erupts/orgs","received_events_url":"https://api.github.com/users/erupts/received_events","repos_url":"https://api.github.com/users/erupts/repos","site_admin":false,"starred_url":"https://api.github.com/users/erupts/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/erupts/subscriptions","type":"User","url":"https://api.github.com/users/erupts","user_view_type":"public"},"html_url":"https://github.com/erupts/erupt-web/commit/497cd16c60c4817beba3170fa36b3776b0f39495","node_id":"C_kwDOFRe12toAKDQ5N2NkMTZjNjBjNDgxN2JlYmEzMTcwZmEzNmIzNzc2YjBmMzk0OTU","parents":[{"html_url":"https://github.com/erupts/erupt-web/commit/d0a2c658cac646d71ce81f738b2df86fbc42c417","sha":"d0a2c658cac646d71ce81f738b2df86fbc42c417","url":"https://api.github.com/repos/erupts/erupt-web/commits/d0a2c658cac646d71ce81f738b2df86fbc42c417"}],"sha":"497cd16c60c4817beba3170fa36b3776b0f39495","url":"https://api.github.com/repos/erupts/erupt-web/commits/497cd16c60c4817beba3170fa36b3776b0f39495"},{"author":{"avatar